async function __salesProdHttpRequest(opts) {
  if (opts && String(opts.url || '').includes('/rest/v1/')) {
    opts = {
      ...opts,
      headers: {
        ...(opts.headers || {}),
        'Accept-Profile': 'sales_prod',
        'Content-Profile': 'sales_prod',
      },
    };
  }
  return this.helpers.httpRequest(opts);
}

// QA-09 — Scenario Runner. Corre UN escenario del catálogo por ejecución.
//
// Existe porque n8n mata cualquier nodo Code a los 300s (N8N_RUNNERS_TASK_TIMEOUT):
// el catálogo entero no cabe en un solo nodo. Al partirlo, cada escenario tarda
// ~35-85s, holgado bajo el límite.
//
// Además limpia SUS PROPIOS datos sintéticos al terminar, en vez de dejarlo para
// el final del lote: si esta ejecución muere, se pierde una prueba, no las 35.
// Lo que aun así se escape lo barre QA-10 (janitor).
//
// Entrada: { scenario, run_id, cw, contact_id, probe }

