const STATE_PATHS = { ENGAGED: [], CONTACTED_1: [], VALUE_PRESENTED: ['VALUE_PRESENTED'], QUOTED: ['QUOTED'],
  PLAN_SELECTED: ['VALUE_PRESENTED', 'QUOTED', 'PLAN_SELECTED'], HANDOFF_HUMAN: ['HANDOFF_HUMAN'],
  WON: ['HANDOFF_HUMAN', 'WON'] };
const EARLY = new Set(['NEW_LEAD', 'CONTACTED_1', 'CONTACTED_2', 'CONTACTED_3']);

async function seed(state, memory, interaction) {
  const now = nowIso();
  const base = { conversation_id: convId, chatwoot_conv_id: CW, chatwoot_contact_id: CONTACT,
    conversation_state: state, customer_engaged: !EARLY.has(state), outbound_sequence_status: 'ACTIVE',
    last_inbound_message_at: now, updated_at: now };
  if (memory) Object.assign(base, memory);
  await patchMemory(base);
  for (const nxt of (STATE_PATHS[state] || [])) {
    await sb('POST', 'rpc/set_conversation_state', { p_conversation_id: convId, p_new_state: nxt,
      p_source: 'qa_n8n_seed', p_metadata: { target_state: state } });
  }
  await sb('PATCH', 'conversaciones?id=eq.' + convId,
    { chatwoot_conv_id: CW, chatwoot_contact_id: CONTACT, ultima_respuesta_at: now }, 'return=minimal');
  if (interaction) {
    // Algunos flujos exigen una interacción activa concreta (p.ej. TOPIC_SELECTION
    // en el gancho Q2) antes de que el botón se considere válido.
    try {
      await sb('POST', 'rpc/set_active_conversation_interaction', { p_conversation_id: convId,
        p_interaction_type: interaction.type,
        p_allowed_actions: interaction.allowed_actions || [],
        p_state: interaction.state || 'AWAITING', p_payload: { qa_seed: true } });
    } catch (e) { /* best effort */ }
  } else if (state === 'PLAN_SELECTED') {
    try {
      await sb('POST', 'rpc/set_active_conversation_interaction', { p_conversation_id: convId,
        p_interaction_type: 'PROPOSAL_CONFIRMATION',
        p_allowed_actions: ['CONTRACT_NOW', 'SEND_PROPOSAL', 'TALK_TO_ADVISOR', 'REVIEW_OTHER_PLAN'],
        p_state: 'AWAITING_PROPOSAL_CONFIRMATION', p_payload: { qa_seed: true } });
    } catch (e) { /* best effort, igual que el motor Python */ }
  }
}

