async function dbCount(table, filter) { const cond = String(filter).replace('{conv}', convId); const r = await sb('GET', table + '?' + cond + '&select=id'); return (r || []).length; }

async function getLatestFollowup(tipo) {
  const rows = await sb('GET', 'scheduled_followups?conversation_id=eq.' + convId
    + '&tipo_followup=eq.' + encodeURIComponent(tipo)
    + '&select=id,status,scheduled_at,retry_count,processed_at,error_msg&order=created_at.desc&limit=1');
  return (rows && rows[0]) || null;
}

async function postJsonWebhook(url, payload, timeout) {
  const r = await __salesProdHttpRequest.call(this, { method: 'POST', url,
    headers: { 'Content-Type': 'application/json', 'x-ql-sync-token': SYNC_TOKEN },
    body: payload, json: true, timeout: timeout || 30000,
    returnFullResponse: true, ignoreHttpStatusErrors: true });
  const code = Number(r.statusCode || r.status || 0);
  if (code < 200 || code >= 300) {
    throw new Error('webhook_failed status=' + code + ' url=' + url + ' body=' + JSON.stringify(r.body || {}).slice(0, 180));
  }
  return r.body;
}

async function waitFor(label, check, timeoutMs, intervalMs) {
  const deadline = Date.now() + (timeoutMs || 90000);
  let last = null;
  while (Date.now() < deadline) {
    try {
      const value = await check();
      if (value) return value;
      last = value;
    } catch (e) {
      last = String(e.message || e).slice(0, 180);
    }
    await sleep(intervalMs || 3000);
  }
  throw new Error(label + ' timeout last=' + JSON.stringify(last).slice(0, 180));
}

async function waitForState(expected, timeoutMs) {
  return await waitFor('state ' + expected, async () => {
    const mem = await getMemory();
    const conv = await getConversation();
    return String(mem.conversation_state || '') === expected && String(conv.estado || '') === expected
      ? { memory: mem, conversation: conv }
      : null;
  }, timeoutMs || 90000, 3000);
}

