async function runOutboundFollowupE2E(scen) {
  await prepareOutboundLeadContext(scen.id);
  await postJsonWebhook(OUTBOUND_INTAKE_WEBHOOK, {
    phone: TEST_PHONE,
    marca: 'KIA',
    quicklink_id: qid,
    nombre_cliente: 'QA N8N ' + scen.id + ' ' + qid,
    modelo: 'SPORTAGE',
    source: 'qa-09-outbound-followup',
    request_id: 'qa-out-fu-' + qid
  }, 30000);

  await waitFor('CONTACTED_1 and CONTACTED_2 pending', async () => {
    const conv = await getConversationByQid();
    if (conv.id) convId = conv.id;
    const mem = await getMemory();
    const fu = convId ? await getLatestFollowup('CONTACTED_2') : null;
    return convId
      && String(mem.conversation_state || '') === 'CONTACTED_1'
      && String(conv.estado || '') === 'CONTACTED_1'
      && fu && fu.status === 'PENDING'
      ? { memory: mem, conversation: conv, followup: fu }
      : null;
  }, 120000, 3000);

  await forceFollowupDue('CONTACTED_2');
  await runSchedulerOnce('CONTACTED_2');
  await waitForState('CONTACTED_2', 90000);
  await waitFor('CONTACTED_3 pending', async () => {
    const fu = await getLatestFollowup('CONTACTED_3');
    return fu && fu.status === 'PENDING' ? fu : null;
  }, 90000, 3000);

  await forceFollowupDue('CONTACTED_3');
  await runSchedulerOnce('CONTACTED_3');
  await waitForState('CONTACTED_3', 90000);
  await sleep((scen.wait || 1) * 1000);
  return await getMemory();
}

async function probeNotes() {
  try {
    const r = await __salesProdHttpRequest.call(this, { method: 'POST', url: PROBE_URL,
      headers: { 'Content-Type': 'application/json', 'x-ql-sync-token': SYNC_TOKEN },
      body: { conv_ids: [CW] }, json: true, timeout: 40000,
      returnFullResponse: true, ignoreHttpStatusErrors: true });
    if (r.statusCode !== 200) return null;
    const convs = (r.body || {}).conversations || [];
    if (!convs.length) return [];
    return convs[0].private_notes || (convs[0].latest_messages || []).filter(m => m.private);
  } catch (e) { return null; }
}

function scenarioNeedsChatwootFixture(scen) {
  return String(scen.group || '').toLowerCase() === 'handoff'
    || (scen.asserts || []).some(a => a.kind === 'chatwoot_note_contains');
}

async function assertChatwootFixtureExists() {
  async function probe(convIds, contactIds) {
    const r = await helpers.httpRequest({ method: 'POST', url: PROBE_URL,
      headers: { 'Content-Type': 'application/json', 'x-ql-sync-token': SYNC_TOKEN },
      body: { conv_ids: convIds, contact_ids: contactIds }, json: true, timeout: 40000,
      returnFullResponse: true, ignoreHttpStatusErrors: true });
    if (r.statusCode !== 200) {
      throw new Error('chatwoot_fixture_preflight_failed status=' + r.statusCode);
    }
    return r.body || {};
  }

  function validConversation(body, id) {
    return (body.conversations || []).find(c => Number(c.id) === Number(id)
      && Number(c.conversation_status) === 200 && c.conversation);
  }

  const first = await probe([CW], [CONTACT]);
  if (validConversation(first, CW)) return;

  const contact = (first.contacts || []).find(c => Number(c.id) === Number(CONTACT));
  const candidates = (contact?.conversations || []).map(c => Number(c.id)).filter(Boolean);
  for (const candidate of candidates) {
    const next = await probe([candidate], []);
    if (validConversation(next, candidate)) {
      CW = candidate;
      return { chatwoot_fixture_recovered: true, cw: CW };
    }
  }

  throw new Error('chatwoot_fixture_missing cw=' + CW + ' contact=' + CONTACT);
}

async function evalAssert(a, ctx) {
  const id = a.id || a.kind, mem = ctx.memory, conv = ctx.conversation;
  const res = (ok, expected, actual) => ({ id, kind: a.kind, pass: !!ok, expected, actual });
  if (a.kind === 'memory_state' || a.kind === 'conv_state') {
    const val = a.kind === 'memory_state' ? mem.conversation_state : conv.estado;
    if ('equals' in a) return res(String(val) === String(a.equals), a.equals, val);
    if ('in' in a) return res(a.in.map(String).indexOf(String(val)) >= 0, a.in, val);
    if ('not_in' in a) return res(a.not_in.map(String).indexOf(String(val)) < 0, 'not ' + JSON.stringify(a.not_in), val);
  }
  if (a.kind === 'memory_field') {
    const val = mem[a.field];
    if (a.not_null) return res(val !== null && val !== undefined, 'not null', val);
    if ('equals' in a) return res(String(val) === String(a.equals), a.equals, val);
    if ('not_equals' in a) return res(String(val) !== String(a.not_equals), '!= ' + a.not_equals, val);
    if (a.null) return res(val === null || val === undefined, 'null', val);
  }
  if (a.kind === 'db_count') {
    const n = await dbCount(a.table, a.filter);
    if ('equals' in a) return res(n === a.equals, a.equals, n);
    if ('min' in a) return res(n >= a.min, '>=' + a.min, n);
    if ('max' in a) return res(n <= a.max, '<=' + a.max, n);
  }
  if (a.kind === 'chatwoot_note_contains') {
    const notes = ctx.notes || [], needle = String(a.contains || '').toUpperCase(), q = String(qid || '');
    const own = notes.filter(n => q && String(n.content || '').indexOf(q) >= 0);
    const hit = own.filter(n => String(n.content || '').toUpperCase().indexOf(needle) >= 0)[0];
    return res(!!hit, 'own note (qid ' + q + ') contains ' + needle,
               { private_notes: notes.length, own_run_notes: own.length });
  }
  return res(false, 'unsupported assert: ' + a.kind, null);
}

async function cleanupSynthetic() {
  let convs = [], leads = [];
  try { convs = await sb('GET', 'conversaciones?quicklink_id=gte.990000000&telefono=like.*998299109*&select=id,lead_id') || []; } catch (e) {}
  try { leads = await sb('GET', 'leads_quicklink?quicklink_id=gte.990000000&telefono_1=like.*998299109*&select=id') || []; } catch (e) {}
  const cids = convs.map(c => c.id);
  const lids = Array.from(new Set(convs.map(c => c.lead_id).filter(Boolean).concat(leads.map(l => l.id))));
  if (!cids.length && !lids.length) return;
  try { const mem = await getMemory(); if (cids.indexOf(mem.conversation_id) >= 0) await patchMemory({ conversation_id: null }); } catch (e) {}
  const ci = cids.join(',');
  const dep = [['scheduled_followups', 'conversation_id'], ['eventos_conversacion', 'conversacion_id'],
    ['eventos_conversacion', 'conversation_id'], ['transferencias_humano', 'conversacion_id'],
    ['datos_calificacion', 'conversation_id'], ['conversation_memory', 'conversation_id'],
    ['agent_decisions', 'conversation_id'], ['sync_queue', 'conversation_id'],
    ['intentos_contacto', 'conversacion_id'], ['whatsapp_interaction_events', 'conversation_id']];
  if (cids.length) {
    for (const d of dep) { try { await sb('DELETE', d[0] + '?' + d[1] + '=in.(' + ci + ')', undefined, 'return=minimal'); } catch (e) {} }
    try { await sb('DELETE', 'conversaciones?id=in.(' + ci + ')', undefined, 'return=minimal'); } catch (e) {}
  }
  if (lids.length) { try { await sb('DELETE', 'leads_quicklink?id=in.(' + lids.join(',') + ')&quicklink_id=gte.990000000', undefined, 'return=minimal'); } catch (e) {} }
}


const scen = input.scenario;
if (!scen) return [{ json: { ok: false, error: 'falta scenario en la entrada' } }];
const runId = input.run_id || null;
const started = nowIso();
let status = 'FAILED', results = [], mem = {}, caseRecordError = null;

try {
  if (scenarioNeedsChatwootFixture(scen)) await assertChatwootFixtureExists();
  if (scen.runner === 'outbound_followup_e2e') {
    mem = await runOutboundFollowupE2E(scen);
  } else {
    await prepareContext(scen.id);
    const sd = scen.seed || {};
    await seed(sd.state || 'ENGAGED', sd.memory, sd.interaction);
    for (const step of (scen.steps || [])) { await sendStep(step); await sleep(step.wait ? step.wait * 1000 : 1000); }
    await sleep((scen.wait || DEFAULT_WAIT) * 1000);
    mem = await getMemory();
  }
  const conv = await getConversation();
  const ctx = { memory: mem, conversation: conv };
  const needNotes = (scen.asserts || []).some(a => a.kind === 'chatwoot_note_contains');
  let notes = null;
  if (needNotes && PROBE) { notes = await probeNotes(); if (notes) ctx.notes = notes; }
  for (const a of (scen.asserts || [])) {
    if (a.kind === 'chatwoot_note_contains') {
      if (!PROBE) { results.push({ id: a.id, kind: a.kind, pass: null, skipped: true, reason: 'probe no habilitado' }); continue; }
      if (notes === null) { results.push({ id: a.id, kind: a.kind, pass: null, skipped: true, reason: 'probe inalcanzable' }); continue; }
    }
    results.push(await evalAssert(a, ctx));
  }
  const real = results.filter(r => !r.skipped);
  status = !real.length ? 'SKIPPED' : (real.every(r => r.pass) ? 'PASSED' : 'FAILED');
} catch (e) {
  status = 'FAILED';
  results.push({ id: 'engine_error', kind: 'engine', pass: false, expected: 'sin error', actual: String(e.message || e).slice(0, 300) });
} finally {
  // Limpieza inmediata: no esperamos al final del lote.
  try { await cleanupSynthetic(); } catch (e) {}
}

const real = results.filter(r => !r.skipped);
const passed = results.filter(r => r.pass).length;
if (runId) {
  try {
    await sb('POST', 'cris_test_cases', { run_id: runId, scenario_id: scen.id, scenario_group: scen.group,
      window_profile: '3m', delivery_mode: 'live', phone: TEST_PHONE_E164, status,
      severity: (scen.group === 'pricing' || scen.group === 'handoff') ? 'P1' : 'P2',
      expected: { title: scen.title, asserts: results.length },
      actual: { passed, total: real.length, conversation_state: mem.conversation_state },
      assertions: results, repro_payload: { seed: scen.seed, steps: scen.steps },
      started_at: started, finished_at: nowIso() }, rep);
  } catch (e) { caseRecordError = String(e.message || e).slice(0, 300); }
}
return [{ json: { ok: true, scenario_id: scen.id, status, passed, total: real.length,
                  conversation_state: mem.conversation_state, conv_id: convId,
                  case_record_error: caseRecordError, results } }];
